```javascript
// Get the canvas and context
const canvas = document.getElementById('canvas');
const ctx = canvas.getContext('2d');

// Set the initial angle and gravity
const initialAngle = parseInt(document.getElementById('initial-angle').value);
const gravity = 9.8; // m/s^2

// Set the pendulum's length and initial velocity
const pendulumLength = 100; // pixels
let velocity = 0;

// Function to update the pendulum's position
function update() {
  // Calculate the pendulum's angle and velocity
  let angle = initialAngle * (Math.PI / 180);
  velocity += gravity * Math.sin(angle) * (pendulumLength / 1000);

  // Update the pendulum's position
  let x = pendulumLength * Math.sin(angle);
  let y = pendulumLength * Math.cos(angle);

  // Clear the canvas and draw the pendulum
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  ctx.beginPath();
  ctx.arc(canvas.width / 2 + x, canvas.height / 2 - y, 5, 0, 2 * Math.PI);
  ctx.fillStyle = 'black';
  ctx.fill();

  // Check if the pendulum has come to rest
  if (Math.abs(velocity) < 0.1) {
    alert('The pendulum has come to rest!');
  } else {
    // Request the next animation frame
    requestAnimationFrame(update);
  }
}

// Function to release the pendulum
document.getElementById('release-button').addEventListener('click', () => {
  update();
});

// Initialize the pendulum's position and velocity
update();
```
