```javascript
function getShopifyOrders() {
  var apiToken = 'YOUR_SHOPIFY_API_TOKEN'; // Replace with your API token
  var shopName = 'YOUR_SHOPIFY_STORE_NAME'; // Replace with your store name
  var apiUrl = 'https://' + shopName + '.shopify.com/api/v2/';
  var accessToken = apiToken;
  var orderIdRange = 1; // Start from the first order

  var funds = ['USD']; // Currency to retrieve orders for
  var endRange = new Date(); // Current date
  var startRange = new Date(endRange.getTime() - 30 * 24 * 60 * 60 * 1000); // Last month

  var params = {
    'limit': 250, // Default limit per call
    'created_at_min': startRange.toISOString(),
    'created_at_max': endRange.toISOString(),
    'currency': funds.join(','),
    'status': 'any' // Retrieve all status, like (new, pending, shipped, cancelled)
  };

  var scriptProperties = PropertiesService.getScriptProperties();
  var sheet = SpreadsheetApp.getActiveSheet();

  function getOrders() {
    var options = {
      'method': 'GET',
      'headers': {
        'Authorization': 'Bearer ' + accessToken,
        'Content-Type': 'application/json'
      },
      'params': params
    };

    var response = UrlFetchApp.fetch(apiUrl + 'orders.json', options);
    var json = JSON.parse(response.getContentText());
    var orders = json.orders;

    if (orders.length > 0) {
      sheet.appendRow(['Order ID', 'Order Date', 'Customer Name', 'Order Total']);
      for (var i = 0; i < orders.length; i++) {
        var order = orders[i];
        var orderID = order.id;
        var orderDate = new Date(order-created_at).toISOString();
        var customerName = order.customer.name;
        var orderTotal = order.total;
        sheet.appendRow([orderID, orderDate, customerName, orderTotal]);
      }
    }
  }

  while (orderIdRange <= json.orders.length) {
    getOrders(orderIdRange);
    orderIdRange += params.limit;
  }
}
```
