#include <pigpio.h>

int main() {
  // Initialize the pigpio library
  gpioInitialise();

  // Set pin 12 to output
  gpioSetup(12, PWM_OUTPUT);

  // Set the PWM frequency to 50Hz
  gpioPWMClear(12);
  gpioPWMSetMode(12, PWM_MODE_MS);
  gpioPWMSetRange(12, 1023);
  gpioPWMSetClockDiv(12, 50);

  // Set the initial duty cycle to 50%
  gpioPWMSet(12, 512);

  // Loop forever, updating the duty cycle every second
  while (1) {
    for (int i = 0; i < 1000; i++) {
      gpioPWMSet(12, i);
      delay(1); // wait 1ms
    }
    for (int i = 1000; i > 0; i--) {
      gpioPWMSet(12, i);
      delay(1); // wait 1ms
    }
  }

  // Clean up
  gpioTerminate();
  return 0;
}
```
